            materials.Dock=DockStyle.Fill;materials.View=View.Details;materials.CheckBoxes=true;materials.FullRowSelect=true;materials.HideSelection=false;materials.SmallImageList=icons;materials.Columns.Add("Material / ícone do item",226);materials.Columns.Add("Registrados",80);materials.Columns.Add("ID",62);materials.Columns.Add("Nv.",44);materials.ItemChecked+=Checked;right.Controls.Add(materials,0,3);
            catalogSummary.Dock=DockStyle.Fill;catalogSummary.ForeColor=Color.SlateGray;catalogSummary.TextAlign=ContentAlignment.MiddleLeft;right.Controls.Add(catalogSummary,0,4);summary.Dock=DockStyle.Fill;summary.TextAlign=ContentAlignment.MiddleLeft;summary.ForeColor=Color.SlateGray;layout.Controls.Add(summary,0,2);
