        static Button Button(string text,int width,Action action){var b=new Button{Text=text,Width=width,Height=31,FlatStyle=FlatStyle.Flat,BackColor=Color.White,Margin=new Padding(0,2,7,0)};b.Click+=(s,e)=>action();return b;}
        int Icon(ResourceDefinition d){int index;if(imageIndexes.TryGetValue(d.id,out index))return index;if(assets==null)return 0;try{using(var image=assets.Image(d.icone)){if(image!=null){var source=(Image)image.Clone();iconSources.Add(source);icons.Images.Add(source);index=icons.Images.Count-1;}else index=0;}}catch{index=0;}imageIndexes[d.id]=index;return index;}
        int CachedIcon(ResourceDefinition d){int index;return imageIndexes.TryGetValue(d.id,out index)?index:0;}
        void LoadVisibleIcons(){if(updating||assets==null||!materials.Visible||materials.Items.Count==0)return;int top=materials.TopItem==null?0:materials.TopItem.Index;for(int i=top;i<Math.Min(materials.Items.Count,top+18);i++){var row=materials.Items[i];row.ImageIndex=Icon((ResourceDefinition)row.Tag);}}
        public Image MapIcon(int template){Image image;if(mapIcons.TryGetValue(template,out image))return image;if(assets==null)return null;ResourceDefinition d;image=null;if(catalog.Definitions.TryGetValue(template,out d))try{image=assets.Image(d.icone);}catch{}mapIcons[template]=image;return image;}
        bool Collectible(int template){ResourceDefinition d;return catalog.Definitions.TryGetValue(template,out d)&&d.item1Id>0&&!String.IsNullOrWhiteSpace(d.nome);}
        public void SetAssets(MapTiles value){foreach(var image in mapIcons.Values)if(image!=null)image.Dispose();mapIcons.Clear();assets=value;map.Tiles=value;imageIndexes.Clear();fingerprint="";RefreshView();}
        public void UpdateFrame(ClientSnapshot snapshot,ResourceFrame resources,string error,List<ResourceMarker> history=null){player=snapshot;frame=resources;known=history??(frame==null?new List<ResourceMarker>():frame.Resources);failure=error??"";map.Player=player;map.Terrain=frame==null?null:frame.Terrain;RefreshView();}
        public void SelectionChanged(){fingerprint="";RefreshView();}
        void SettingsChanged(){if(!updatingSettings&&SearchSettingsChanged!=null)SearchSettingsChanged(region.Text,(double)radius.Value);}
        public void SetSearchSettings(string name,double value){updatingSettings=true;try{region.Text=name??"";radius.Value=(decimal)value;}finally{updatingSettings=false;}RefreshView();}
        List<ResourceMarker> VisibleResources(){if(frame==null)return new List<ResourceMarker>();return known.Where(r=>r.HorizontalDistance<=(double)radius.Value&&selected().Contains(r.TemplateId)).ToList();}
        void Checked(object sender,ItemCheckedEventArgs e){if(updating)return;var d=e.Item.Tag as ResourceDefinition;if(d==null||selected().Contains(d.id)==e.Item.Checked)return;if(MaterialSelectionChanged!=null)MaterialSelectionChanged(d.id,e.Item.Checked);if(!deferred&&IsHandleCreated){deferred=true;BeginInvoke(new Action(()=>{deferred=false;if(!IsDisposed){fingerprint="";RefreshView();}}));}}
        void RefreshView(){if(updating||IsDisposed)return;if(IsHandleCreated&&!Visible){stale=true;return;}updating=true;try{var chosen=new HashSet<int>(selected());double range=(double)radius.Value;
            var visible=frame==null?new List<ResourceMarker>():known.Where(r=>r.HorizontalDistance<=range&&chosen.Contains(r.TemplateId)).OrderBy(r=>r.HorizontalDistance).Take(300).ToList();map.Resources=known.Where(r=>chosen.Contains(r.TemplateId)||Collectible(r.TemplateId)).ToList();map.Invalidate();uint current=nearby.SelectedItems.Count==1?((ResourceMarker)nearby.SelectedItems[0].Tag).InstanceId:0;
            string nearbyNext=String.Join(";",visible.Select(r=>r.InstanceId+":"+r.Distance.ToString("F1")+(r.Historical?"h":"")+(r.LevelAllowed?"":"x")));if(nearbyNext!=nearbySignature){nearbySignature=nearbyNext;nearby.BeginUpdate();nearby.Items.Clear();foreach(var r in visible){ResourceDefinition d=catalog.Definitions[r.TemplateId];var item=new ListViewItem(r.Name+(r.Historical?" (registrado)":""),Icon(d)){Tag=r,ForeColor=r.LevelAllowed?RotaTheme.Good:Rubi.Accent};item.SubItems.Add(r.TemplateId.ToString());item.SubItems.Add(r.Distance.ToString("F1"));item.SubItems.Add(r.RequiredLevel.ToString());nearby.Items.Add(item);if(r.InstanceId==current)item.Selected=true;}nearby.EndUpdate();}
            var nearIds=new HashSet<int>(frame==null?new int[0]:known.Where(r=>r.HorizontalDistance<=range).Select(r=>r.TemplateId));string query=search.Text.Trim();
            string next=query+"|"+onlyNear.Checked+"|"+onlySelected.Checked+"|"+String.Join(",",chosen.OrderBy(id=>id))+"|"+(onlyNear.Checked?String.Join(",",nearIds.OrderBy(id=>id)):"");if(next!=fingerprint){var definitions=catalog.Definitions.Values.Where(d=>(chosen.Contains(d.id)||(d.item1Id>0&&!String.IsNullOrWhiteSpace(d.nome)))&&(!onlyNear.Checked||nearIds.Contains(d.id)||chosen.Contains(d.id))&&(!onlySelected.Checked||chosen.Contains(d.id))&&(query.Length==0||d.nome.IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0||d.id.ToString().Contains(query)||(d.itemNome??"").IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0)).OrderBy(d=>d.nome).ToList();
            materials.BeginUpdate();materials.Items.Clear();foreach(var d in definitions){var item=new ListViewItem(String.IsNullOrWhiteSpace(d.nome)?"Recurso "+d.id:d.nome,CachedIcon(d)){Tag=d,Checked=chosen.Contains(d.id)};item.SubItems.Add("0");item.SubItems.Add(d.id.ToString());item.SubItems.Add(catalog.GatherLevel(d).ToString());item.ToolTipText=(d.itemNome??"Item sem nome")+" · Item ID "+d.item1Id;materials.Items.Add(item);}materials.ShowItemToolTips=true;materials.EndUpdate();fingerprint=next;listedCount=definitions.Count;}
            var counts=new Dictionary<int,int>();if(frame!=null)foreach(var r in known)if(r.HorizontalDistance<=range){int n;counts.TryGetValue(r.TemplateId,out n);counts[r.TemplateId]=n+1;}
            foreach(ListViewItem row in materials.Items){var definition=(ResourceDefinition)row.Tag;int n;counts.TryGetValue(definition.id,out n);string text=n.ToString();if(row.SubItems[1].Text!=text)row.SubItems[1].Text=text;}catalogSummary.Text=chosen.Count+" materiais escolhidos · "+listedCount+" na lista\r\nImagem: ícone do item. Sem imagem: quadrado neutro.";
            summary.Text=player==null?"Conecte a um personagem. Marque os materiais desejados na lista à direita.":frame==null?"Leitura de recursos indisponível: "+failure:visible.Count+" na lista · Mapa: todos os locais conhecidos dos tipos escolhidos · "+frame.Resources.Count+" carregadas · Atualizado "+frame.ReadAt.ToString("HH:mm:ss")+" · Verde: você · Amarelo: material · Vermelho: nível insuficiente";
